const mov = $('Consultar movimiento').first().json || {};
const filas = $('Cargar agentes').all().map(i => i.json).filter(r => r.id && r.telegram_id && r.activo && r.rol === 'trafico');
function norm(s) { return String(s === undefined || s === null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim(); }
const tipo = norm(mov.TipoPedido);
const grupo = (tipo === 'import' || tipo === 'export' || tipo === 'internacional') ? 'internacional' : (tipo === 'nacional' ? 'nacional' : 'otro');
const alias = norm(mov.Agente);
const admins = filas.filter(r => r.admin === true);
let dest = [];
let motivo = 'ok';
if (!mov.Movimiento || mov.error) { dest = admins; motivo = 'sin_movimiento'; }
else if (grupo === 'internacional') { dest = filas.filter(r => norm(r.grupo) === 'internacional'); if (!dest.length) { dest = admins; motivo = 'sin_agentes_internacional'; } }
else { dest = alias ? filas.filter(r => norm(r.nombre) === alias) : []; if (!dest.length) { dest = admins; motivo = 'agente_no_encontrado:' + String(mov.Agente || ''); } }
const meta = { _grupo: grupo, _agente: String(mov.Agente || ''), _motivo: motivo, _movimiento: String(mov.Movimiento || '') };
if (!dest.length) { return [{ json: Object.assign({ sin_destinatarios: true }, meta) }]; }
return dest.map(r => ({ json: Object.assign({}, r, meta) }));

